#!/usr/bin/env python3

from argparse import ArgumentParser
from dataclasses import dataclass, field
from hashlib import sha256
from pathlib import Path
import re


SOURCES = {
    "American": ("hyph-en-us.tex", "f4ffcd96c5cbc886bdad23f95dcae8edc3cd3620eae62f7946eceda97c4e68f8"),
    "British": ("hyph-en-gb.tex", "e95bb4ab350f620c41c231c4785d7bdb4f91949d3e631b30e08b3ead3c340a52"),
}


@dataclass
class PatternNode:
    children: dict = field(default_factory=dict)
    score: int = 0


def pack_scores(scores):
    digits = ''.join(f'{value:x}' for value in scores).rstrip('0')
    if not digits:
        return 0
    leading_zeros = len(digits) - len(digits.lstrip('0'))
    digits = digits[leading_zeros:]
    score = int(digits[::-1] + f'{leading_zeros:x}', 16)
    if leading_zeros >= 16 or score >= 1 << 64:
        raise ValueError("Pattern score exceeds its encoded field")
    return score


def set_pattern(root, letters, scores):
    node = root
    for letter in letters:
        label = 0 if letter == '.' else ord(letter) - ord('a') + 1
        node = node.children.setdefault(label, PatternNode())
    node.score = pack_scores(scores)


def read_patterns(source, digest):
    payload = source.read_bytes()
    if sha256(payload).hexdigest() != digest:
        raise ValueError(f"Unexpected upstream SHA-256 for {source}")
    body = re.sub(r'%[^\n]*', '', payload.decode('utf-8'))
    root = PatternNode()

    for pattern in re.search(r'\\patterns\s*\{([^}]*)\}', body)[1].split():
        letters = []
        scores = [0]
        for character in pattern:
            if character.isdecimal():
                scores[-1] = int(character)
            else:
                letters.append(character)
                scores.append(0)
        set_pattern(root, letters, scores)

    for word in re.search(r'\\hyphenation\s*\{([^}]*)\}', body)[1].split():
        pieces = word.split('-')
        split = 0
        letters = ''.join(pieces)
        scores = [0, 0] + [14] * (len(letters) - 1) + [0, 0]
        for piece in pieces[:-1]:
            split += len(piece)
            scores[split + 1] = 15
        set_pattern(root, '.' + letters + '.', scores)
    return root


class PackedPatterns:
    def __init__(self):
        self.edges = [0]
        self.outgoing_edges = {}
        self.scores = {0: 0}

    def add(self, node):
        entries = []
        entries_count = len(node.children)
        if not entries_count:
            return 0

        for index, (label, child) in enumerate(sorted(node.children.items()), start=1):
            descendants = self.add(child)
            score = self.scores.setdefault(child.score, len(self.scores))
            if score >= 1 << 10 or descendants >= 1 << 16:
                raise ValueError("Pattern table exceeds its encoded field")
            entries.append(label | ((index == entries_count) << 5) | (descendants << 6) | (score << 22))

        key = tuple(entries)
        if key not in self.outgoing_edges:
            self.outgoing_edges[key] = len(self.edges)
            self.edges.extend(entries)
        return self.outgoing_edges[key]


def write_array(lines, value_type, name, values, columns):
    lines.append(f"constexpr std::{value_type} {name}[] = {{")
    for offset in range(0, len(values), columns):
        group = values[offset:offset + columns]
        lines.append("    " + ", ".join(f"0x{value:x}" for value in group) + ",")
    lines.extend(("};", ""))


def main():
    parser = ArgumentParser(description="Compile pinned TeX English hyphenation tables.")
    parser.add_argument("source_directory", type=Path)
    parser.add_argument("--output", type=Path, default=Path(__file__).with_name("patterns.inc"))
    args = parser.parse_args()

    compiled = PackedPatterns()
    roots = {
        name: compiled.add(read_patterns(args.source_directory / filename, digest))
        for name, (filename, digest) in SOURCES.items()
    }
    lines = [
        "// Derived from pinned tex-hyphen pattern files. See LICENSE-en-us.txt and LICENSE-en-gb.txt.",
        "// Generated by generate_hyphenation.py.",
    ]
    for name, root in roots.items():
        if root >= 1 << 16:
            raise ValueError("Pattern root exceeds its encoded field")
        lines.append(f"constexpr std::uint16_t k{name}EnglishRoot = {root};")
    lines.append("")
    write_array(lines, "uint32_t", "kEnglishPatternEdges", compiled.edges, 8)
    write_array(lines, "uint64_t", "kEnglishPatternScores", list(compiled.scores), 8)
    args.output.write_text("\n".join(lines), encoding="ascii")
    print(f"{len(compiled.edges)} edges and {len(compiled.scores)} scores")


if __name__ == "__main__":
    main()
